def compute(vars):
    threshold = 500000
    qualifying_years = {
        "2019": vars["v1"] > threshold,
        "2018": vars["v2"] > threshold,
        "2017": vars["v3"] > threshold,
    }
    count = sum(qualifying_years.values())
    return {
        "value": count,
        "trace": {
            "threshold": threshold,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years",
            },
        },
    }
